function numberLines(text, opts){
  opts=opts||{}; var fmt=opts.format||'1.'; var start=opts.start!=null?opts.start:1;
  var lines=String(text||'').split(/\r?\n/); var out=[];
  for(var i=0;i<lines.length;i++){
    if(lines[i]==='' && opts.skipEmpty){ out.push(''); continue; }
