    if(fmt==='1)') p=n+') ';
    else if(fmt==='-') p='- ';
    else if(fmt==='*') p='* ';
    else if(fmt==='01.') p=(n<10?'0'+n:n)+'. ';
    else p=n+'. ';
    out.push(p+lines[i]);
  }
  return out.join('\n');
